/*--------------------------------------------------------------------------*/

void led_detect_started( void )
{
	led_flash( LED_FLASH_NOW , LED_RED , 100 , 300000 , 1 , 1 , 1 ) ; 
}

/*--------------------------------------------------------------------------*/

void led_detect_done( void )
{
	led_flash( LED_FLASH_NOW , LED_GREEN , 100 , 3000 , 1 , 1 , 1 ) ; 
}

/*--------------------------------------------------------------------------*/

void led_detect_in_progress( void )
{
	led_flash( LED_FLASH_NOW , LED_GREEN , 100 , 200 , 200 , 1 , LED_LOOP ) ; 
}

/*--------------------------------------------------------------------------*/

void led_detect_err_can0( void )
{
	led_reset();

	os_tsk_wait(1000);	

	led_usr_detect_err(LED_USR_ERR_CAN_DEV0,1);
}

